# Browserprüfung für persönliche Kenntnisbestände.
"""Both TF inventory tabs: real files, confirmation, saved lists, offline owner isolation."""
import argparse
from browser_realtime import check_pages
from check_work_report_layout import STATIC

def fixture():
    scripts='\n'.join((STATIC/name).read_text() for name in ['messages.js','knowledge-inventory.js'])
    checks=r'''
(async()=>{
const assert=(ok,msg)=>{if(!ok)throw Error(msg);};let owner=7,online=true,writes=0;Object.defineProperty(navigator,'onLine',{get:()=>online});const stored={places:[],classes:[]},identity=()=>({owner_id:owner,tf_number:'787100',first_name:'Mira',last_name:'Beispiel'}),values={places:[{station_name:'Test <b> Bahnhof',ds100:'AA G',known_until:'2025-01-01'}],classes:[{series:'0186',valid_until:'2029-10-06'}]};
window.fetch=async(url,options={})=>{if(!online)throw Error('Offline');const kind=url.includes('/places')?'places':'classes';let data;if(options.method==='POST'){assert(options.body.get('file') instanceof File,'Real CSV file');if(url.endsWith('/preview'))data={identity:identity(),items:values[kind],owner_token:'bound',summary:{file_sha256:'f'.repeat(64),source_rows:1,added:1,existing:0,conflicts:0}};else{assert(options.body.get('confirmed')==='true'&&options.body.get('owner_token')==='bound','Explicit target-bound confirmation');writes++;stored[kind]=values[kind];data={identity:identity(),summary:{added:1,existing:0,conflicts:0}};}}else data={identity:identity(),items:owner===7?stored[kind]:[]};return {ok:true,status:200,json:async()=>data};};
for(const kind of ['places','classes']){const root=document.getElementById(kind);await KnowledgeInventory.mount({id:7},root,kind);const file=root.querySelector('input[type=file]'),dt=new DataTransfer();dt.items.add(new File([kind==='places'?'Bahnhof;DS100;Kundig bis;\nTest;AA G;2025-01-01;':'Baureihe;Gültig bis;\n0186;2029-10-06;'],'Bestand.csv',{type:'text/csv'}));file.files=dt.files;const before=writes;await file.onchange();assert(writes===before,'Preview never saves');assert(!root.querySelector('[data-knowledge-preview]').hidden,'Preview appears');assert(root.querySelector('[data-knowledge-preview]').textContent.includes('787100'),'Target TF visible');assert(root.querySelectorAll('[data-knowledge-saved] tbody tr').length===0,'Saved list untouched before confirmation');await root.querySelector('[data-knowledge-confirm]').onclick();assert(writes===before+1,'Exactly one confirmation');assert(root.querySelector('[data-knowledge-preview]').hidden&&!file.value,'Draft and file cleared');assert(root.querySelectorAll('[data-knowledge-saved] tbody tr').length===1,'Saved inventory remains visible');assert(!root.querySelector('tbody b'),'Personal text is literal');assert((await KnowledgeInventory.cache(7,kind)).items.length===1,'Inventory cached for own TF');}
assert(document.getElementById('classes').textContent.includes('0186'),'Leading zeros retained');
online=false;const offline=document.createElement('div');document.body.append(offline);await KnowledgeInventory.mount({id:7},offline,'places');assert(offline.querySelectorAll('[data-knowledge-saved] tbody tr').length===1,'Own inventory available offline');owner=8;const other=document.createElement('div');document.body.append(other);await KnowledgeInventory.mount({id:8},other,'places');assert(other.querySelectorAll('tbody tr').length===0,'No other TF inventory');await KnowledgeInventory.cache(8,'places',{identity:{owner_id:7},items:[]}).then(()=>{throw Error('Cross-owner cache write');},()=>{});assert(document.documentElement.scrollWidth<=innerWidth+1,'Narrow page remains within viewport');parent.postMessage({layoutStatus:'pass'},'*');
})().catch(error=>parent.postMessage({layoutStatus:'fail',message:error.stack},'*'));
'''
    css='\n'.join((STATIC/name).read_text() for name in ['tf-portal.css','work-report.css','portal-theme.css','responsive.css'])
    return '<!doctype html><meta charset="utf-8"><style>'+css+'</style><main><section class="train-panel"><div id="places"></div><div id="classes"></div></section></main><script>'+scripts+checks+'</script>'
if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--output-dir',required=True);args=parser.parse_args();check_pages(fixture,args.output_dir,label='TF location and rolling-stock inventories')
